{{(() => {
  const ratings = [
    Rating47Copy.value,
    Rating48Copy.value,
    Rating49Copy.value,
    Rating50Copy.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);
  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: APPROFONDIRE I TEMI GIOIELLERIA E ORO DA INVESTIMENTO";
  }

  const allAtLeastTwo = ratings.every(r => r >= 2);
  return allAtLeastTwo
    ? "OBIETTIVO DELLA SETTIMANA RAGGIUNTO: APPROFONDIRE I TEMI GIOIELLERIA E ORO DA INVESTIMENTO"
    : "OBIETTIVO DELLA SETTIMANA NON RAGGIUNTO: APPROFONDIRE I TEMI GIOIELLERIA E ORO DA INVESTIMENTO";
})()
}}

