(() => {
  const ratings = [
    Rating47Copy.value,
    Rating48Copy.value,
    Rating49Copy.value,
    Rating50Copy.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);
  if (hasInvalidRating) {
    return "blue";
  }

  const allAtLeastTwo = ratings.every(r => r >= 2);
  return allAtLeastTwo ? "green" : "red";
})()
}}
